function collapseDuplicateMedidasAsk(text2) {
  if (!text2?.trim()) return text2;
  const askRe = /¿Qué medidas aproximadas tiene el espacio\?/gi;
  const matches = [...text2.matchAll(askRe)];
  if (matches.length <= 1) return text2;
  let seen = false;
  return text2.replace(askRe, (m5) => {
    if (seen) return "";
    seen = true;
    return m5;
  }).replace(/\n{3,}/g, "\n\n").trim();
}
